BEGIN;
INSERT INTO public.admin_users(id,email,password_hash,role,is_active) VALUES('f8800000-0000-4000-8000-000000000001','contact-admin@example.test','test-only','admin',true),('f8800000-0000-4000-8000-000000000002','contact-member@example.test','test-only','team_member',true);
INSERT INTO public.admin_sessions(id,admin_user_id,token_hash) VALUES('f8800000-0000-4000-8000-000000000003','f8800000-0000-4000-8000-000000000001',repeat('1',64)),('f8800000-0000-4000-8000-000000000004','f8800000-0000-4000-8000-000000000002',repeat('2',64));
DO $$ DECLARE actor uuid:='f8800000-0000-4000-8000-000000000001';sid uuid:='f8800000-0000-4000-8000-000000000003';member uuid:='f8800000-0000-4000-8000-000000000002';msid uuid:='f8800000-0000-4000-8000-000000000004';v jsonb;u uuid;c uuid;j public.delivery_jobs;clean text;doc jsonb;BEGIN
 IF has_function_privilege('anon','public.mutate_contact_upload(uuid,text,text,text,jsonb,text,text)','EXECUTE') OR has_function_privilege('authenticated','public.contact_inbox(uuid,uuid,uuid,jsonb,integer)','EXECUTE') THEN RAISE EXCEPTION 'Browser contact RPC';END IF;
 v:=public.mutate_contact_upload(NULL,repeat('a',64),repeat('b',64),'create',jsonb_build_object('filename','fictional.png','mime','image/png','bytes',100,'sha256',repeat('c',64),'key','quarantine/'||gen_random_uuid()||'/'||gen_random_uuid()),repeat('d',64),repeat('e',64));u:=(v->>'uploadId')::uuid;
 BEGIN PERFORM public.mutate_contact_upload(u,repeat('f',64),repeat('b',64),'status','{}',NULL,NULL);RAISE EXCEPTION 'Foreign proof accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 doc:=jsonb_build_object('name','Fictional contact','email','fictional-contact@example.test','type','general','message','A fictional contact message for the local SQL fixture only.','uploadId',u,'uploadProof',repeat('a',64));
 BEGIN PERFORM public.submit_contact(doc,repeat('1',64),repeat('2',64));RAISE EXCEPTION 'Unscanned attachment accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_UPLOAD' THEN RAISE;END IF;END;
 v:=public.mutate_contact_upload(u,repeat('a',64),repeat('b',64),'complete','{}',repeat('3',64),repeat('4',64));
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['contact_upload_scan']) WHERE payload->>'uploadId'=u::text;
 IF public.reserve_contact_scan_object(j.id,gen_random_uuid()) IS NOT NULL THEN RAISE EXCEPTION 'Forged scan lease';END IF;
 clean:=public.reserve_contact_scan_object(j.id,j.lease_token);
 IF clean IS NULL OR public.reserve_contact_scan_object(j.id,j.lease_token) IS DISTINCT FROM clean THEN RAISE EXCEPTION 'Untracked scan object';END IF;
 IF NOT public.finish_contact_upload_scan(j.id,j.lease_token,clean,'image/png',90,repeat('5',64),NULL) THEN RAISE EXCEPTION 'Scan commit';END IF;
 c:=public.submit_contact(doc,repeat('1',64),repeat('2',64));
 IF public.submit_contact(doc,repeat('1',64),repeat('2',64))<>c OR(SELECT count(*) FROM public.delivery_jobs WHERE payload->>'contactId'=c::text)<>2 THEN RAISE EXCEPTION 'Contact retry duplicated';END IF;
 BEGIN PERFORM public.submit_contact(doc,repeat('6',64),repeat('2',64));RAISE EXCEPTION 'Attachment rebound to another contact';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_UPLOAD' THEN RAISE;END IF;END;
 BEGIN PERFORM public.mutate_contact_upload(u,repeat('a',64),repeat('b',64),'remove','{}',repeat('7',64),repeat('8',64));RAISE EXCEPTION 'Attached file removed anonymously';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
 BEGIN PERFORM public.contact_inbox(member,msid,c,'{}',1);RAISE EXCEPTION 'Team member read chapter contacts';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 v:=public.contact_inbox(actor,sid,c,'{}',1);
 IF v::text LIKE '%quarantine/%' OR v::text LIKE '%clean/%' OR v::text LIKE '%proof_hash%' OR NOT(v->'items'->0->'attachment'->>'canDownload')::boolean THEN RAISE EXCEPTION 'Inbox metadata boundary';END IF;
 v:=public.contact_attachment_download(actor,sid,c,gen_random_uuid());IF v->>'key'<>clean THEN RAISE EXCEPTION 'Protected download';END IF;
 PERFORM public.mutate_contact_record(actor,sid,c,1,'status','{"status":"resolved"}',NULL,gen_random_uuid());
 PERFORM public.mutate_contact_record(actor,sid,c,2,'hold','{"enabled":true,"reason":"Fictional operational hold for SQL test"}','test-only',gen_random_uuid());
 UPDATE public.contact_submissions SET resolved_at=now()-interval '181 days' WHERE id=c;
 PERFORM public.claim_contact_upload_cleanup(50);
 IF(SELECT redacted_at FROM public.contact_submissions WHERE id=c) IS NOT NULL OR(SELECT deleted_at FROM public.upload_intents WHERE id=u) IS NOT NULL THEN RAISE EXCEPTION 'Contact hold ignored';END IF;
 PERFORM public.mutate_contact_record(actor,sid,c,3,'hold','{"enabled":false}','test-only',gen_random_uuid());
 IF NOT EXISTS(SELECT 1 FROM public.claim_contact_upload_cleanup(50) WHERE id=u) THEN RAISE EXCEPTION 'Resolved retention not queued';END IF;
 IF(SELECT email FROM public.contact_submissions WHERE id=c)<>'' OR(SELECT status FROM public.contact_submissions WHERE id=c)<>'redacted' THEN RAISE EXCEPTION 'Contact identity not redacted';END IF;
 IF NOT public.finish_contact_upload_cleanup(u) THEN RAISE EXCEPTION 'Contact cleanup acknowledgement';END IF;
 IF(SELECT filename FROM public.upload_intents WHERE id=u)<>'' THEN RAISE EXCEPTION 'Contact cleanup filename erasure';END IF;
 BEGIN PERFORM public.contact_attachment_download(actor,sid,c,gen_random_uuid());RAISE EXCEPTION 'Retained object still downloadable';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
END $$;
ROLLBACK;
